{"code": "import os
# 查看 compose 目录结构
for root, dirs, files in os.walk("compose"):
    level = root.replace("compose", "").count(os.sep)
    indent = " " * 2 * level
    print(f"{indent}{os.path.basename(root)}/")
    subindent = " " * 2 * (level + 1)
    for file in files[:10]:
        print(f"{subindent}{file}")
